using System;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
namespace OpenAntiLag {
 public static class PlayerTests {
  static int count;static void Check(bool value,string message="Player assertion failed"){if(!value)throw new Exception(message);}static void Test(string name,Action action){action();count++;Console.WriteLine("PASS "+name);}static void Throws(Action action){bool caught=false;try{action();}catch{caught=true;}Check(caught,"Expected failure");}
  static void Temp(Action<string> action){string root=Path.Combine(Path.GetTempPath(),"OpenAntiLag-player-test-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{action(root);}finally{Directory.Delete(root,true);}}
  static OptimizationOrchestrator Optimizer(Engine engine,ISystemClient system,Func<Task<bool>> acquire=null){return new OptimizationOrchestrator(new ExistingOptimizationBackend(engine,system),acquire??(()=>Task.FromResult(true)),()=>{});}
  public static int Run(){
   Test("Player standard and competitive profiles exclude experimental and privileged options",delegate{foreach(var profile in new[]{PlayerProfile.Standard,PlayerProfile.Competitive}){var o=OptimizationOrchestrator.Options(profile);Check(o.GameMode&&!o.CpuReady&&!o.PcieReady&&!o.Timer&&!o.DisableMouseAcceleration);Check(o.DisableCapture==(profile==PlayerProfile.Competitive));}Throws(()=>OptimizationOrchestrator.Options(PlayerProfile.Custom));});
   Test("Player primary applies real existing Engine and restores original plan",delegate{var host=new FakeHost();using(var engine=new Engine(host,new MemoryStore())){var optimizer=Optimizer(engine,new TestSystemClient());Check(optimizer.Enable(PlayerProfile.Standard,OptimizationOrchestrator.Options(PlayerProfile.Standard),new string[0]).GetAwaiter().GetResult());Check(engine.IsActive&&host.CopiedFrom==FakeHost.Original&&optimizer.Status.Stage==OptimizationStage.Enabled);optimizer.Restore().GetAwaiter().GetResult();Check(engine.State.Phase=="Disabled"&&host.Current==FakeHost.Original&&!optimizer.Status.HasProfile);}});
   Test("Player existing active profile is not silently overwritten",delegate{var host=new FakeHost();using(var engine=new Engine(host,new MemoryStore())){engine.Enable(ProfileOptions.Gaming());string backup=engine.State.OwnedPlan;var optimizer=Optimizer(engine,new TestSystemClient());Check(!optimizer.Enable(PlayerProfile.Standard,OptimizationOrchestrator.Options(PlayerProfile.Standard),new string[0]).GetAwaiter().GetResult());Check(engine.State.OwnedPlan==backup&&optimizer.Status.Stage==OptimizationStage.ErrorIncomplete);}});
   Test("Player apply failure reports actual rollback state",delegate{var host=new FakeHost {Fail="create"};using(var engine=new Engine(host,new MemoryStore())){var optimizer=Optimizer(engine,new TestSystemClient());Check(!optimizer.Enable(PlayerProfile.Standard,OptimizationOrchestrator.Options(PlayerProfile.Standard),new string[0]).GetAwaiter().GetResult());Check(optimizer.Status.Stage==OptimizationStage.ErrorRestored&&host.Current==FakeHost.Original);}});
   Test("Player mutation gate prevents writes while another operation runs",delegate{var host=new FakeHost();using(var engine=new Engine(host,new MemoryStore())){var optimizer=Optimizer(engine,new TestSystemClient(),()=>Task.FromResult(false));Check(!optimizer.Enable(PlayerProfile.Standard,OptimizationOrchestrator.Options(PlayerProfile.Standard),new string[0]).GetAwaiter().GetResult()&&host.Writes==0);}});
   Test("Player recovery never claims all restored after one module fails",delegate{using(var engine=new Engine(new FakeHost(),new MemoryStore())){var optimizer=Optimizer(engine,new TestSystemClient());bool pending=true;optimizer.RestoreAll(new[]{new RecoveryModule {Name="Broken",Pending=()=>pending,Restore=()=>{throw new IOException("driver unavailable");}}}).GetAwaiter().GetResult();Check(optimizer.Operations().Last().Success==false&&optimizer.Status.Message.Contains("Не все"));}});
   Test("Player unified recovery stops subsequent modules on UAC cancellation",delegate{using(var engine=new Engine(new FakeHost(),new MemoryStore())){var optimizer=Optimizer(engine,new TestSystemClient());bool next=false;optimizer.RestoreAll(new[]{new RecoveryModule {Name="UAC",Pending=()=>true,Restore=()=>{throw new OperationCanceledException();}},new RecoveryModule {Name="Next",Pending=()=>true,Restore=()=>{next=true;return "bad";}}}).GetAwaiter().GetResult();Check(!next);}});
   Test("Steam library manifests identify installed CS2 without process-name guessing",delegate{Temp(root=>{string steam=Path.Combine(root,"steam"),library=Path.Combine(root,"second"),apps=Path.Combine(library,"steamapps"),game=Path.Combine(apps,"common","Counter-Strike Global Offensive"),exe=Path.Combine(game,"game","bin","win64","cs2.exe");Directory.CreateDirectory(Path.Combine(steam,"steamapps"));Directory.CreateDirectory(Path.GetDirectoryName(exe));File.WriteAllText(exe,"");File.WriteAllText(Path.Combine(steam,"steamapps","libraryfolders.vdf"),"\"libraryfolders\" {\"1\" {\"path\" \""+library.Replace("\\","\\\\")+"\"}}");File.WriteAllText(Path.Combine(apps,"appmanifest_730.acf"),"\"AppState\" { \"appid\" \"730\" \"name\" \"Counter-Strike 2\" \"installdir\" \"Counter-Strike Global Offensive\" }");var found=new GameDetectionService(()=>new[]{steam}).Scan();Check(found.Count==1&&found[0].Id=="steam:730"&&found[0].Executable==exe);});});
   Test("Player store persists selection, profile and explicit automatic consent",delegate{Temp(root=>{string exe=Path.Combine(root,"cs2.exe");File.WriteAllText(exe,"");var game=GameDetectionService.Manual(exe);game.Profile=PlayerProfile.Competitive;game.Automatic=true;var preferences=new PlayerPreferences {SelectedGame=game.Id,SetupComplete=true};preferences.Games.Add(game);var store=new PlayerStore(Path.Combine(root,"library.json"));store.Save(preferences);var loaded=store.Load();Check(loaded.SelectedGame==game.Id&&loaded.Games.Single().Automatic&&loaded.Games[0].Profile==PlayerProfile.Competitive);File.WriteAllText(Path.Combine(root,"library.json"),"{}");Throws(()=>store.Load());});});
   Test("Player automatic start and game exit restore only the owned user profile",delegate{Temp(root=>{string exe=Path.Combine(root,"cs2.exe");File.WriteAllText(exe,"");var game=new InstalledGame {Id="steam:730",Name="CS2",Executable=exe,Automatic=true};var processes=new[]{new GameProcess {Id=42,Name="cs2",Path=exe}};var host=new FakeHost();using(var engine=new Engine(host,new MemoryStore())){var store=new MemoryGameSessionStore();var system=new TestSystemClient();var session=new GameSessionController(Optimizer(engine,system),store);session.Tick(game,processes).GetAwaiter().GetResult();Check(engine.IsActive&&store.Value!=null&&!store.Value.Applying);session.Tick(game,new GameProcess[0]).GetAwaiter().GetResult();Check(engine.State.Phase=="Disabled"&&store.Value==null&&system.DisableCalls==0);}});});
   Test("Player session restart restores recorded ownership when game already ended",delegate{Temp(root=>{string exe=Path.Combine(root,"game.exe");File.WriteAllText(exe,"");var host=new FakeHost();using(var engine=new Engine(host,new MemoryStore())){engine.Enable(OptimizationOrchestrator.Options(PlayerProfile.Standard));var store=new MemoryGameSessionStore {Value=new GameSessionMarker {GameId="x",Executable=exe,OwnedPlan=engine.State.OwnedPlan,SeenGameRunning=true}};var session=new GameSessionController(Optimizer(engine,new TestSystemClient()),store);session.Tick(null,new GameProcess[0]).GetAwaiter().GetResult();Check(engine.State.Phase=="Disabled"&&store.Value==null);}});});
   Test("Player session refuses to restore a different or ambiguous profile",delegate{Temp(root=>{string exe=Path.Combine(root,"game.exe");File.WriteAllText(exe,"");using(var engine=new Engine(new FakeHost(),new MemoryStore())){engine.Enable(ProfileOptions.Gaming());var store=new MemoryGameSessionStore {Value=new GameSessionMarker {GameId="x",Executable=exe,OwnedPlan=Guid.NewGuid().ToString()}};var session=new GameSessionController(Optimizer(engine,new TestSystemClient()),store);session.Tick(null,new GameProcess[0]).GetAwaiter().GetResult();Check(engine.State.Phase=="Enabled"&&store.Value!=null);store.Value.Applying=true;session.Tick(null,new GameProcess[0]).GetAwaiter().GetResult();Check(engine.State.Phase=="Enabled");}});});
   Test("Player automatic optimization requires consent and verified executable path",delegate{Temp(root=>{string exe=Path.Combine(root,"cs2.exe");File.WriteAllText(exe,"");var game=new InstalledGame {Id="730",Name="CS2",Executable=exe};using(var engine=new Engine(new FakeHost(),new MemoryStore())){var session=new GameSessionController(Optimizer(engine,new TestSystemClient()),new MemoryGameSessionStore());session.Tick(game,new[]{new GameProcess {Name="cs2",Path=exe}}).GetAwaiter().GetResult();Check(engine.State.Phase=="Disabled");game.Automatic=true;session.Tick(game,new[]{new GameProcess {Name="cs2",Path=Path.Combine(root,"other.exe")}}).GetAwaiter().GetResult();Check(engine.State.Phase=="Disabled");}});});
   Test("Player manual game profile waits for launch and restores after observed exit",delegate{Temp(root=>{string exe=Path.Combine(root,"game.exe");File.WriteAllText(exe,"");var game=new InstalledGame {Id="game",Name="Game",Executable=exe};using(var engine=new Engine(new FakeHost(),new MemoryStore())){var marker=new MemoryGameSessionStore();var session=new GameSessionController(Optimizer(engine,new TestSystemClient()),marker);session.ApplyManual(game,new GameProcess[0]).GetAwaiter().GetResult();session.Tick(game,new GameProcess[0]).GetAwaiter().GetResult();Check(engine.IsActive&&!marker.Value.SeenGameRunning);session.Tick(game,new[]{new GameProcess {Id=1,Path=exe,Name="game"}}).GetAwaiter().GetResult();Check(marker.Value.SeenGameRunning);session.Tick(game,new GameProcess[0]).GetAwaiter().GetResult();Check(engine.State.Phase=="Disabled");}});});
   Test("Player manual disable suppresses automatic reapply for the current game run",delegate{Temp(root=>{string exe=Path.Combine(root,"game.exe");File.WriteAllText(exe,"");var game=new InstalledGame {Id="game",Name="Game",Executable=exe,Automatic=true};var processes=new[]{new GameProcess {Id=2,Path=exe,Name="game"}};using(var engine=new Engine(new FakeHost(),new MemoryStore())){var optimizer=Optimizer(engine,new TestSystemClient());var session=new GameSessionController(optimizer,new MemoryGameSessionStore());session.Tick(game,processes).GetAwaiter().GetResult();session.SuppressCurrentRun(game,processes);optimizer.Restore().GetAwaiter().GetResult();session.Tick(game,processes).GetAwaiter().GetResult();session.Tick(game,processes).GetAwaiter().GetResult();Check(engine.State.Phase=="Disabled");}});});
   Test("Player UAC cancellation leaves system and user profiles unapplied",delegate{using(var engine=new Engine(new FakeHost(),new MemoryStore())){var optimizer=Optimizer(engine,new TestSystemClient {CancelEnable=true});optimizer.Enable(PlayerProfile.Custom,ProfileOptions.Gaming(),new[]{"hags"}).GetAwaiter().GetResult();Check(engine.State.Phase=="Disabled"&&optimizer.Status.Stage==OptimizationStage.ErrorRestored);}});
   return count;
  }
 }
}
